API Gateway Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway Container container

Container_Boundary(api_gateway_container, "API Gateway Container") {
    Component(Router__Routing_Controller, "Router & Routing Controller", "AWS API Gateway", "Handles perimeter security, routing, and internal traffic distribution to core domain containers.")
    Component(Rate_Limiter__Idempotency_Validator, "Rate Limiter & Idempotency Validator", "AWS API Gateway / Redis", "Performs distributed rate limiting and idempotency tracking using the caching layer.")
    Component(Security__TLS_Termination_Filter, "Security & TLS Termination Filter", "AWS API Gateway (TLS/JWT)", "Handles TLS termination, JWT validation, and perimeter security checks.")
}

Rel(Security__TLS_Termination_Filter, Router__Routing_Controller, "Forwards validated and secure client requests")
Rel(Router__Routing_Controller, Rate_Limiter__Idempotency_Validator, "Validates rate limits and idempotency via Redis")

@enduml

Frontend Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Frontend Container", "Frontend Container") {
    Component(spa, "Single Page Application (SPA)", "TypeScript / Client-Side Rendering", "Handles user interactions, browsing, purchasing, and reviewing books on the client side with end-to-end type safety.")
    Component(ssr, "Server-Side Rendering (SSR) Engine", "TypeScript / Node.js", "Renders initial pages on the server to ensure fast load times and optimized Core Web Vitals tracking.")
    Component(cdn, "Content Delivery Network (CDN) Integration", "CDN Edge Caching / CSP / SRI", "Delivers static and dynamic assets securely with OWASP Top-10 mitigation and aggressive edge caching.")
}

Rel(spa, ssr, "Hydrates and exchanges application state", "HTTPS")
Rel(ssr, cdn, "Serves cached assets and pages", "HTTPS")
@enduml

Core Domain Containers.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Domain Containers container

Container_Boundary(core_domain_containers, "Core Domain Containers") {
    Component(Catalogue_Component, "Catalogue Component", "Microservice Component / OpenAPI / Protobuf", "Manages product catalogue data and handles domain-specific requests.")
    Component(Cart_Checkout_Component, "Cart/Checkout Component", "Microservice Component / OpenAPI / Protobuf", "Handles shopping cart state, checkout processes, and related user actions.")
    Component(Recommendations_Component, "Recommendations Component", "Microservice Component / OpenAPI / Protobuf", "Generates personalized product recommendations for users.")
    Component(Reviews_Component, "Reviews Component", "Microservice Component / OpenAPI / Protobuf", "Manages customer reviews, ratings, and feedback.")
}

Rel(Catalogue_Component, Cart_Checkout_Component, "Provides product details for checkout", "Internal REST / gRPC")

@enduml

Background Job Scheduler Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(background_job_scheduler_container, "Background Job Scheduler Container") {
    Component(Scheduler_Worker, "Scheduler Worker", "Cron worker / Scheduler", "Manages asynchronous batch tasks securely and reliably, coordinating with external systems and internal caching.")
    Component(Distributed_Lock_Manager, "Distributed Lock Manager", "Redis", "Provides distributed locking and session management to prevent duplicate job execution.")
    Component(Job_Definition_Provider, "Job Definition Provider", "AWS Systems Manager Parameter Store", "Stores externalized job definitions and dynamic cron expressions.")
}

Rel(Scheduler_Worker, Distributed_Lock_Manager, "Acquires distributed locks via TCP to prevent duplicate job execution", "TCP")
Rel(Scheduler_Worker, Job_Definition_Provider, "Retrieves externalized job definitions and dynamic cron expressions", "AWS SDK / HTTPS")

@enduml

Observability Sidecar & Config Agents.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Observability Sidecar & Config Agents", "Observability Sidecar & Config Agents") {
    Component(Telemetry Collector, "Telemetry Collector", "OpenTelemetry Sidecar", "Handles standardized telemetry collection and exports metrics and traces.")
    Component(Configuration Agent, "Configuration Agent", "AWS Systems Manager Parameter Store Agent", "Retrieves and manages dynamic configuration updates for core containers.")
    Component(Secrets Manager Agent, "Secrets Manager Agent", "AWS Secrets Manager Agent", "Securely injects secrets and credentials into the core containers.")
}

Rel(Telemetry Collector, Configuration Agent, "Shares shared container runtime resources", "")
Rel(Configuration Agent, Secrets Manager Agent, "Coordinates secret and configuration synchronization", "")

@enduml
